import { AggregateRoot, Id } from '@Architecture/Domain';
import { InvitationSnapshot } from '@Contexts/Groups/Domain/Invitation/DTOs';
import { InvitationCreatedEvent } from '@Contexts/Groups/Domain/Invitation/Events/InvitationEvents';

/**
 * An invitation to a group: a link. Its id is generated by the domain, long and random, and it is the only proof a
 * joiner needs: whoever holds it may read it and join, any number of times over. It changes nothing of the group when
 * it is created; accepting it is the group's business (Group.join). Whether the inviting account may invite is decided
 * by the command that creates it, from the group's members.
 */
export class Invitation extends AggregateRoot {
  private constructor(
    id: Id,
    version: number,
    readonly groupId: Id,
    readonly invitedBy: Id,
    readonly createdAt: Date,
  ) {
    super(id, version);
  }

  /**
   * Issues an invitation: a new link, with a generated id. The name is `issue`, not `create`: a handler that issues one
   * and another aggregate's create() in the same use case would be read as the other aggregate's behaviour (storm).
   */
  static issue({ groupId, invitedBy, at }: { groupId: Id; invitedBy: Id; at: Date }): Invitation {
    const invitation = new Invitation(Id.generate(), 0, groupId, invitedBy, at);
    invitation.record(
      InvitationCreatedEvent.set({
        invitationId: invitation._id.value,
        groupId: groupId.value,
        invitedBy: invitedBy.value,
        createdAt: at.toISOString(),
      }),
    );
    return invitation;
  }

  /** Reconstitutes a stored invitation. It records nothing, and refuses corrupted data by throwing. */
  static fromSnapshot(snapshot: InvitationSnapshot): Invitation {
    const createdAt = new Date(snapshot.createdAt);
    if (!snapshot.id || !snapshot.groupId || !snapshot.invitedBy || Number.isNaN(createdAt.getTime())) {
      throw new Error(`Corrupted invitation ${snapshot.id}`);
    }
    return new Invitation(
      new Id(snapshot.id),
      snapshot.version,
      new Id(snapshot.groupId),
      new Id(snapshot.invitedBy),
      createdAt,
    );
  }

  toSnapshot(): InvitationSnapshot {
    return {
      id: this._id.value,
      groupId: this.groupId.value,
      invitedBy: this.invitedBy.value,
      createdAt: this.createdAt.toISOString(),
      version: this.version,
    };
  }
}
